func TestGettersConsentRequest(t *testing.T) {
	t.Run("GetRequestID", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &ConsentRequest{}
		var expected string
		obj.RequestID = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetRequestID(), "getter should return the property value")
	})

	t.Run("GetRequestID_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *ConsentRequest
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetRequestID() // Should return zero value
	})

	t.Run("GetGrantWrite", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &ConsentRequest{}
		var expected *bool
		obj.GrantWrite = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetGrantWrite(), "getter should return the property value")
	})

	t.Run("GetGrantWrite_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &ConsentRequest{}
		obj.GrantWrite = nil

		// Act & Assert
		assert.Nil(t, obj.GetGrantWrite(), "getter should return nil when property is nil")
	})

	t.Run("GetGrantWrite_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *ConsentRequest
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetGrantWrite() // Should return zero value
	})

}

